ROLE_HIERARCHY = {
    "viewer": set(),
    "editor": {"viewer"},
    "admin": {"editor"},
}

ROLE_PERMISSIONS = {
    "viewer": {"read_report"},
    "editor": {"edit_report"},
    "admin": {"delete_user"},
}


def effective_permissions(role):
    permissions = set(ROLE_PERMISSIONS.get(role, set()))
    for parent in ROLE_HIERARCHY.get(role, set()):
        permissions |= effective_permissions(parent)
    return permissions


def can(role, action):
    return action in effective_permissions(role)


checks = [
    ("viewer", "read_report"),
    ("editor", "read_report"),
    ("editor", "delete_user"),
    ("admin", "delete_user"),
]

for role, action in checks:
    decision = "ALLOW" if can(role, action) else "DENY"
    print(f"{role} -> {action}: {decision}")
